<?php
namespace App\Http\Controllers;
use App\Models\Order; use App\Services\BiteshipShippingService; use Illuminate\Http\JsonResponse; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Log; use Throwable;
class ShippingOrderController extends Controller { public function create(Request $request,Order $order,BiteshipShippingService $shipping):RedirectResponse{abort_unless($request->user()->role==='admin',403);if($order->payment_status!=='paid'&&$order->payment_method!=='cod')return back()->withErrors(['shipping'=>'Pembayaran pesanan harus sudah lunas sebelum pengiriman dibuat.']);if($order->biteship_order_id)return back()->with('status','Pengiriman Biteship sudah dibuat untuk pesanan ini.');try{$shipping->syncOrderResponse($order,$shipping->createOrder($order));}catch(Throwable $e){Log::error('Biteship order creation failed.',['order_id'=>$order->id,'exception'=>$e]);return back()->withErrors(['shipping'=>'Pengiriman Biteship gagal dibuat. Silakan coba lagi.']);}return back()->with('status','Pengiriman Biteship berhasil dibuat.');}
 public function webhook(Request $request):JsonResponse{$signatureKey=config('services.biteship.webhook_signature_key');$signatureSecret=config('services.biteship.webhook_signature_secret');if(!$signatureKey||!$signatureSecret){Log::critical('Biteship webhook rejected because signature configuration is missing.');return response()->json(['message'=>'Webhook authentication is not configured.'],503);} $provided=(string)$request->header($signatureKey);if(!$provided||!hash_equals($signatureSecret,$provided))return response()->json(['message'=>'Invalid webhook signature.'],401);$payload=$request->all();$biteshipOrderId=$payload['order_id']??$payload['id']??null;if(!$biteshipOrderId)return response()->json(['status'=>'ignored']);$order=Order::where('biteship_order_id',$biteshipOrderId)->first();if(!$order)return response()->json(['status'=>'ignored']);$status=$payload['status']??null;$normalizedStatus=is_string($status)?strtolower(preg_replace('/(?<!^)[A-Z]/','_$0',$status)):null;$waybill=$payload['courier_waybill_id']??data_get($payload,'courier.waybill_id');$trackingId=$payload['tracking_id']??data_get($payload,'courier.tracking_id');$trackingUrl=$payload['courier_link']??data_get($payload,'courier.link');$updates=array_filter(['shipping_status'=>$status,'tracking_number'=>$waybill,'biteship_tracking_id'=>$trackingId,'shipping_tracking_url'=>$trackingUrl],static fn($value)=>$value!==null&&$value!=='');if($normalizedStatus&&in_array($normalizedStatus,['picked','in_transit','dropping_off','delivered'],true))$updates['shipped_at']=$order->shipped_at??now();if($normalizedStatus==='delivered'&&$order->status!=='cancelled'){$updates['status']='completed';}elseif($normalizedStatus&&in_array($normalizedStatus,['picked','in_transit','dropping_off'],true)&&$order->status!=='completed'){$updates['status']='shipped';}elseif($normalizedStatus==='cancelled'&&$order->status!=='completed'){$updates['status']='cancelled';$updates['cancelled_at']=$order->cancelled_at??now();}$previous=$order->status;$order->update($updates);if(isset($updates['status'])&&$updates['status']!==$previous)$order->recordStatusChange($updates['status'],'biteship','Shipping webhook status update.');return response()->json(['status'=>'ok']);}
